import { serve } from "@hono/node-server";
import { Hono } from "hono";

const app = new Hono();

app.get("/", (c) => c.json({ name: "{{name}}", ok: true }));
app.get("/hello/:who", (c) => c.text(`Hello, ${c.req.param("who")}!`));

// roll gives the port to listen on.
serve({ fetch: app.fetch, port: Number(process.env.PORT) || 3000 });
